from fastapi import APIRouter, Depends, HTTPException
from kubernetes_asyncio import client

router = APIRouter(prefix="/k8s/namespaces")

@router.get("/{namespace}/alert-rules/{rule_name}")
async def get_prometheus_rule(
    namespace: str,
    rule_name: str,
    current_user: User = Depends(get_current_user),
    custom_api: client.CustomObjectsApi = Depends(get_k8s_custom_api)
):
    if namespace not in current_user.permitted_namespaces:
        raise HTTPException(status_code=403, detail="Forbidden: Namespace outside permitted scope")

    try:
        rule_obj = await custom_api.get_namespaced_custom_object(
            group="monitoring.coreos.com",
            version="v1",
            namespace=namespace,
            plural="prometheusrules",
            name=rule_name
        )
    except client.exceptions.ApiException as e:
        raise HTTPException(status_code=e.status, detail="Monitoring rule not found")

    return {
        "namespace": namespace,
        "rule_name": rule_name,
        "spec": rule_obj.get("spec", {})
    }
